import { useEffect, useState } from "react";
import {
  Button,
  Card,
  CardBody,
  CardHeader,
  CardTitle,
  Col,
  Form,
  FormGroup,
  Input,
  Label,
  Row,
  Spinner,
} from "reactstrap";
import { Plus, Trash2 } from "react-feather";
import {
  getWelcomeWhatsappConfig,
  saveWelcomeWhatsappConfig,
  getWelcomeWhatsappLogs,
} from "../../../apis/welcomeWhatsapp";
import { tostify, tostifySuccess } from "../../../components/Tostify";

const emptyParameter = () => ({
  type: "text",
  parameterName: "",
  text: "",
  subType: "",
  index: "",
});

const emptyComponent = () => ({
  type: "body",
  parameters: [],
});

const defaultForm = {
  isEnabled: false,
  apiUrl: "https://wa2.netsofters.com/api/external-api-bridge/send-message",
  securityKey: "",
  messagingProduct: "whatsapp",
  recipientType: "individual",
  messageType: "template",
  templateName: "order_confirmation",
  templateLanguageCode: "en_US",
  countryCodePrefix: "91",
  components: [],
};

const WelcomeMsg = () => {
  const [form, setForm] = useState(defaultForm);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [logs, setLogs] = useState([]);
  const [logsLoading, setLogsLoading] = useState(false);

  const loadConfig = async () => {
    setLoading(true);
    try {
      const data = await getWelcomeWhatsappConfig();
      if (data?.msg === "invalid token or expired token") {
        tostify("Session expired. Please login again.");
        return;
      }
      if (data?.error) {
        tostify(data.error);
        return;
      }
      if (data) {
        setForm({
          isEnabled: data.isEnabled ?? false,
          apiUrl:
            data.apiUrl ||
            "https://wa2.netsofters.com/api/external-api-bridge/send-message",
          securityKey: data.securityKey || "",
          messagingProduct: data.messagingProduct || "whatsapp",
          recipientType: data.recipientType || "individual",
          messageType: data.messageType || "template",
          templateName: data.templateName || "",
          templateLanguageCode: data.templateLanguageCode || "en_US",
          countryCodePrefix: data.countryCodePrefix || "91",
          components: Array.isArray(data.components) ? data.components : [],
        });
      }
    } catch (err) {
      tostify(
        err?.response?.data?.error ||
          "Failed to load welcome message configuration"
      );
    } finally {
      setLoading(false);
    }
  };

  const loadLogs = async () => {
    setLogsLoading(true);
    try {
      const data = await getWelcomeWhatsappLogs(1, 10);
      if (data?.msg === "invalid token or expired token") {
        return;
      }
      setLogs(data?.data || []);
    } catch (err) {
      setLogs([]);
    } finally {
      setLogsLoading(false);
    }
  };

  useEffect(() => {
    loadConfig();
    loadLogs();
  }, []);

  const updateField = (field, value) => {
    setForm((prev) => ({ ...prev, [field]: value }));
  };

  const addComponent = () => {
    setForm((prev) => ({
      ...prev,
      components: [...prev.components, emptyComponent()],
    }));
  };

  const removeComponent = (index) => {
    setForm((prev) => ({
      ...prev,
      components: prev.components.filter((_, i) => i !== index),
    }));
  };

  const updateComponent = (index, field, value) => {
    setForm((prev) => {
      const components = [...prev.components];
      components[index] = { ...components[index], [field]: value };
      return { ...prev, components };
    });
  };

  const addParameter = (compIndex) => {
    setForm((prev) => {
      const components = [...prev.components];
      const params = [...(components[compIndex].parameters || [])];
      params.push(emptyParameter());
      components[compIndex] = { ...components[compIndex], parameters: params };
      return { ...prev, components };
    });
  };

  const removeParameter = (compIndex, paramIndex) => {
    setForm((prev) => {
      const components = [...prev.components];
      const params = (components[compIndex].parameters || []).filter(
        (_, i) => i !== paramIndex
      );
      components[compIndex] = { ...components[compIndex], parameters: params };
      return { ...prev, components };
    });
  };

  const updateParameter = (compIndex, paramIndex, field, value) => {
    setForm((prev) => {
      const components = [...prev.components];
      const params = [...(components[compIndex].parameters || [])];
      params[paramIndex] = { ...params[paramIndex], [field]: value };
      components[compIndex] = { ...components[compIndex], parameters: params };
      return { ...prev, components };
    });
  };

  const handleSave = async () => {
    if (
      !form.apiUrl ||
      !form.securityKey ||
      !form.messagingProduct ||
      !form.recipientType ||
      !form.messageType ||
      !form.templateName ||
      !form.templateLanguageCode
    ) {
      return tostify(
        "Please fill all required fields: API URL, Security Key, messaging_product, recipient_type, type, template name, and language code"
      );
    }

    setSaving(true);
    try {
      const resp = await saveWelcomeWhatsappConfig(form);
      if (resp?.msg === "invalid token or expired token") {
        tostify("Session expired. Please login again.");
        return;
      }
      if (resp?.msg === "success") {
        tostifySuccess("Welcome WhatsApp configuration saved successfully");
        if (resp?.data) {
          setForm({
            isEnabled: resp.data.isEnabled ?? form.isEnabled,
            apiUrl: resp.data.apiUrl || form.apiUrl,
            securityKey: resp.data.securityKey || form.securityKey,
            messagingProduct: resp.data.messagingProduct || form.messagingProduct,
            recipientType: resp.data.recipientType || form.recipientType,
            messageType: resp.data.messageType || form.messageType,
            templateName: resp.data.templateName || form.templateName,
            templateLanguageCode:
              resp.data.templateLanguageCode || form.templateLanguageCode,
            countryCodePrefix: resp.data.countryCodePrefix || form.countryCodePrefix,
            components: Array.isArray(resp.data.components)
              ? resp.data.components
              : form.components,
          });
        }
        loadLogs();
      } else {
        tostify(resp?.error || "Failed to save configuration");
      }
    } catch (err) {
      tostify(
        err?.response?.data?.error ||
          "Failed to save welcome message configuration"
      );
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center py-5">
        <Spinner color="primary" />
      </div>
    );
  }

  return (
    <>
      <div style={{ display: "flex", alignItems: "center", marginBottom: "1.5rem" }}>
        <h3 className="text-primary mb-0">
          <b>Welcome WhatsApp Message</b>
        </h3>
        <div className="ml-auto d-flex align-items-center">
          <div className="form-switch form-check-primary">
            <Input
              type="switch"
              id="welcome-msg-enabled"
              name="isEnabled"
              checked={form.isEnabled}
              onChange={(e) => updateField("isEnabled", e.target.checked)}
            />
          </div>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle tag="h4">API Configuration</CardTitle>
        </CardHeader>
        <CardBody>
          <Form>
            <Row>
              <Col md="6">
                <FormGroup>
                  <Label>
                    API URL <span className="text-danger">*</span>
                  </Label>
                  <Input
                    value={form.apiUrl}
                    onChange={(e) => updateField("apiUrl", e.target.value)}
                    placeholder="https://wa2.netsofters.com/api/external-api-bridge/send-message"
                  />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <Label>
                    x-security-key <span className="text-danger">*</span>
                  </Label>
                  <Input
                    type="password"
                    value={form.securityKey}
                    onChange={(e) => updateField("securityKey", e.target.value)}
                    placeholder="Enter security key"
                  />
                </FormGroup>
              </Col>
            </Row>
          </Form>
        </CardBody>
      </Card>

      <Card className="mt-2">
        <CardHeader>
          <CardTitle tag="h4">Message Payload (Required Fields)</CardTitle>
        </CardHeader>
        <CardBody>
          <Form>
            <Row>
              <Col md="4">
                <FormGroup>
                  <Label>
                    messaging_product <span className="text-danger">*</span>
                  </Label>
                  <Input
                    value={form.messagingProduct}
                    onChange={(e) =>
                      updateField("messagingProduct", e.target.value)
                    }
                  />
                </FormGroup>
              </Col>
              <Col md="4">
                <FormGroup>
                  <Label>
                    recipient_type <span className="text-danger">*</span>
                  </Label>
                  <Input
                    value={form.recipientType}
                    onChange={(e) =>
                      updateField("recipientType", e.target.value)
                    }
                  />
                </FormGroup>
              </Col>
              <Col md="4">
                <FormGroup>
                  <Label>
                    type <span className="text-danger">*</span>
                  </Label>
                  <Input
                    value={form.messageType}
                    onChange={(e) => updateField("messageType", e.target.value)}
                  />
                </FormGroup>
              </Col>
              <Col md="4">
                <FormGroup>
                  <Label>
                    template.name <span className="text-danger">*</span>
                  </Label>
                  <Input
                    value={form.templateName}
                    onChange={(e) => updateField("templateName", e.target.value)}
                    placeholder="order_confirmation"
                  />
                </FormGroup>
              </Col>
              <Col md="4">
                <FormGroup>
                  <Label>
                    template.language.code <span className="text-danger">*</span>
                  </Label>
                  <Input
                    value={form.templateLanguageCode}
                    onChange={(e) =>
                      updateField("templateLanguageCode", e.target.value)
                    }
                    placeholder="en_US"
                  />
                </FormGroup>
              </Col>
              <Col md="4">
                <FormGroup>
                  <Label>Country Code Prefix</Label>
                  <Input
                    value={form.countryCodePrefix}
                    onChange={(e) =>
                      updateField("countryCodePrefix", e.target.value)
                    }
                    placeholder="91"
                  />
                  <small className="text-muted">
                    Mobile number is auto-filled from candidate registration (e.g. 91 + mobile)
                  </small>
                </FormGroup>
              </Col>
            </Row>
          </Form>
        </CardBody>
      </Card>

      <Card className="mt-2">
        <CardHeader className="d-flex align-items-center">
          <CardTitle tag="h4" className="mb-0">
            Template Components (Optional)
          </CardTitle>
          <Button
            color="primary"
            size="sm"
            className="ml-auto"
            onClick={addComponent}
          >
            <Plus size={14} className="mr-50" /> Add Component
          </Button>
        </CardHeader>
        <CardBody>
          {form.components.length === 0 ? (
            <p className="text-muted mb-0">
              No components added. Click &quot;Add Component&quot; to add template
              body/header/button parameters.
            </p>
          ) : (
            form.components.map((comp, compIndex) => (
              <Card key={compIndex} className="border mb-2">
                <CardBody>
                  <div className="d-flex align-items-center mb-1">
                    <h5 className="mb-0">Component {compIndex + 1}</h5>
                    <Button
                      color="danger"
                      size="sm"
                      outline
                      className="ml-auto"
                      onClick={() => removeComponent(compIndex)}
                    >
                      <Trash2 size={14} />
                    </Button>
                  </div>
                  <Row>
                    <Col md="4">
                      <FormGroup>
                        <Label>type</Label>
                        <Input
                          type="select"
                          value={comp.type || "body"}
                          onChange={(e) =>
                            updateComponent(compIndex, "type", e.target.value)
                          }
                        >
                          <option value="body">body</option>
                          <option value="header">header</option>
                          <option value="button">button</option>
                        </Input>
                      </FormGroup>
                    </Col>
                  </Row>

                  <div className="d-flex align-items-center mb-1">
                    <Label className="mb-0">Parameters</Label>
                    <Button
                      color="flat-primary"
                      size="sm"
                      className="ml-2"
                      onClick={() => addParameter(compIndex)}
                    >
                      <Plus size={14} className="mr-50" /> Add Parameter
                    </Button>
                  </div>

                  {(comp.parameters || []).length === 0 ? (
                    <small className="text-muted">No parameters added.</small>
                  ) : (
                    (comp.parameters || []).map((param, paramIndex) => (
                      <Row key={paramIndex} className="align-items-end mb-1">
                        <Col md="2">
                          <FormGroup>
                            <Label>type</Label>
                            <Input
                              value={param.type || "text"}
                              onChange={(e) =>
                                updateParameter(
                                  compIndex,
                                  paramIndex,
                                  "type",
                                  e.target.value
                                )
                              }
                            />
                          </FormGroup>
                        </Col>
                        <Col md="3">
                          <FormGroup>
                            <Label>parameter_name</Label>
                            <Input
                              value={param.parameterName || ""}
                              onChange={(e) =>
                                updateParameter(
                                  compIndex,
                                  paramIndex,
                                  "parameterName",
                                  e.target.value
                                )
                              }
                              placeholder="first_name"
                            />
                          </FormGroup>
                        </Col>
                        <Col md="4">
                          <FormGroup>
                            <Label>text</Label>
                            <Input
                              value={param.text || ""}
                              onChange={(e) =>
                                updateParameter(
                                  compIndex,
                                  paramIndex,
                                  "text",
                                  e.target.value
                                )
                              }
                              placeholder="{{firstname}} or static text"
                            />
                          </FormGroup>
                        </Col>
                        <Col md="2">
                          <FormGroup>
                            <Label>index</Label>
                            <Input
                              type="number"
                              value={param.index ?? ""}
                              onChange={(e) =>
                                updateParameter(
                                  compIndex,
                                  paramIndex,
                                  "index",
                                  e.target.value
                                )
                              }
                            />
                          </FormGroup>
                        </Col>
                        <Col md="1">
                          <Button
                            color="danger"
                            size="sm"
                            outline
                            onClick={() => removeParameter(compIndex, paramIndex)}
                          >
                            <Trash2 size={14} />
                          </Button>
                        </Col>
                      </Row>
                    ))
                  )}
                </CardBody>
              </Card>
            ))
          )}
          <small className="text-muted d-block mt-1">
            Use placeholders in text: {"{{firstname}}"}, {"{{lastname}}"}, {"{{fullname}}"}, {"{{mobile}}"}, {"{{email}}"}, {"{{city}}"}
          </small>
        </CardBody>
      </Card>

      <div className="d-flex justify-content-end mt-2 mb-2">
        <Button color="primary" onClick={handleSave} disabled={saving}>
          {saving ? <Spinner size="sm" /> : "Save Configuration"}
        </Button>
      </div>

      <Card>
        <CardHeader>
          <CardTitle tag="h4">Recent Send Logs</CardTitle>
        </CardHeader>
        <CardBody>
          {logsLoading ? (
            <Spinner size="sm" color="primary" />
          ) : logs.length === 0 ? (
            <p className="text-muted mb-0">No messages sent yet.</p>
          ) : (
            <div className="table-responsive">
              <table className="table table-sm">
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Mobile</th>
                    <th>Status</th>
                    <th>Error</th>
                  </tr>
                </thead>
                <tbody>
                  {logs.map((log) => (
                    <tr key={log.id || log._id}>
                      <td>
                        {log.createdAt
                          ? new Date(log.createdAt).toLocaleString()
                          : "-"}
                      </td>
                      <td>{log.mobile || "-"}</td>
                      <td>
                        <span
                          className={`badge badge-${
                            log.status === "success"
                              ? "success"
                              : log.status === "skipped"
                              ? "warning"
                              : "danger"
                          }`}
                        >
                          {log.status}
                        </span>
                      </td>
                      <td>{log.error || "-"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardBody>
      </Card>
    </>
  );
};

export default WelcomeMsg;
